class Solution:
    def countPuddles(self, m: int, n: int, cells: List[List[int]]) -> List[int]:
        par = {}; out = []; comps = 0
        def find(x):
            while par[x] != x: par[x] = par[par[x]]; x = par[x]
            return x
        for r, c in cells:
            if (r, c) not in par:
                par[(r, c)] = (r, c); comps += 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nb = (r + dr, c + dc)
                    if nb in par:
                        a, b = find(nb), find((r, c))
                        if a != b: par[a] = b; comps -= 1
            out.append(comps)
        return out

