#include <bits/stdc++.h>
using namespace std;
// Union-find over wet cells: each new cell starts its own puddle, then merges with wet neighbours.
unordered_map<long long,long long> par;
long long find(long long x){ while(par[x]!=x){ par[x]=par[par[x]]; x=par[x]; } return x; }
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
  long long m,n; int k; cin>>m>>n>>k; int comps=0;
  for(int i=0;i<k;i++){ long long r,c; cin>>r>>c; long long id=r*n+c;
    if(!par.count(id)){ par[id]=id; comps++;
      int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
      for(int d=0;d<4;d++){ long long x=r+dr[d], y=c+dc[d]; if(x<0||y<0||x>=m||y>=n) continue; long long nb=x*n+y;
        if(par.count(nb)){ long long a=find(nb), b=find(id); if(a!=b){ par[a]=b; comps--; } } } }
    cout<<comps<<(i+1<k?" ":"\n"); } }

